run.step = Step::compute;
const api::CloudView view{in.x.span(), in.y.span(), in.z.span(), in.ids.span()};
const api::Request request =
    o.output == api::OutputKind::supports ? api::Request(api::SupportsRequest{o.k})
    : o.output == api::OutputKind::points ? api::Request(api::PointsRequest{o.k})
    : o.output == api::OutputKind::flat   ? api::Request(api::FlatRequest{o.k, o.mcs, o.z, o.selection})
                                          : api::Request(api::FullRequest{o.k});
Result<api::Product> product = api::compute(session, view, request, &run.report);

// Voie de l'arbre d'ordre K de la sortie supports (livraison L2b, docs/SORTIES.md paragraphe 11) : full_tower,
// build_order_full au masque 16379 de FULL (journal des graines sur l'ordre K, extraction de l'ordre K) ; order_tree,
// build_order au masque 7035. La regle de L2, ecrite d'avance, a decide livrer_L2b (mesure appariee G4 du 5 octobre
// 2026, rapports supports/full de l'etage tree a W48 de 1,21, 1,18 et 1,09) : full_tower est la voie de compute.
// order_tree reste disponible et jugee : les portes mhgp11_api_supports_route* exigent MHGP11SP et manifeste
// identiques a l'octet par les deux voies, et les registres du journal egaux.
enum class SupportsRoute : u8 { full_tower, order_tree };
inline constexpr SupportsRoute kSupportsRoute = SupportsRoute::full_tower;

Result<FullTower> full_tower(Session& session, const CloudView& view, Order k, RunReport& report) noexcept {
  Result<FullDomain> domain = prepare_domain(session, view, k, report);
  if (!domain.ok()) return domain.outcome();
  MemoryBudget& budget = session.budget();
  Stopwatch tree_clock;
  Result<FullTower> tower =
      build_full(std::move(domain.value()), budget, nullptr, api_detail::full_params(), &session.pool());
  if (!tower.ok()) return tower.outcome();
  close_stage(report, Stage::tree, tree_clock, budget);
  return std::move(tower).take();

Result<OrderTree> order_tree(Session& session, const CloudView& view, Order k, RunReport& report, bool strict,
                             api_detail::SupportsRoute route = api_detail::SupportsRoute::order_tree,
                             api_detail::SupportsDiagnostics* diagnostics = nullptr) noexcept {
  Result<FullDomain> domain = prepare_domain(session, view, k, report, strict);
  if (!domain.ok()) return domain.outcome();
  MemoryBudget& budget = session.budget();
  Stopwatch tree_clock;
  u64 attach_ns = 0;
  SeedLogRegisters* registers = diagnostics == nullptr ? nullptr : &diagnostics->log;
  Result<OrderTree> tree =
      route == api_detail::SupportsRoute::full_tower
          ? build_order_full(std::move(domain.value()), k, budget, api_detail::full_params(), &session.pool(),
                             nullptr, &attach_ns, registers)
          : build_order(std::move(domain.value()), k, budget, api_detail::order_params(), &session.pool(), nullptr,
                        &attach_ns, registers);

Result<SupportsParts> supports_parts(Session& session, const CloudView& view, Order k, RunReport& report,
                                     api_detail::SupportsRoute route,
                                     api_detail::SupportsDiagnostics* diagnostics) noexcept {
  Result<OrderTree> tree = order_tree(session, view, k, report, false, route, diagnostics);
  if (!tree.ok()) return tree.outcome();
  MemoryBudget& budget = session.budget();
  Stopwatch output_clock;
  Result<supports::SupportHierarchy> hierarchy =
      supports::build_support_hierarchy(tree.value(), budget, &session.pool());
  if (!hierarchy.ok()) return hierarchy.outcome();
  close_stage(report, Stage::output, output_clock, budget);
  return SupportsParts{std::move(tree).take(), std::move(hierarchy).take()};

Result<Product> compute(Session& session, const CloudView& cloud, const Request& request,
                        RunReport* report) noexcept {
  RunReport local;
  if (const SupportsRequest* wanted = std::get_if<SupportsRequest>(&request))
    return api_detail::compute_supports(session, cloud, wanted->k, api_detail::kSupportsRoute, report);

const FullRequest* full = std::get_if<FullRequest>(&request);
if (full == nullptr) return fail(Reason::parameter_out_of_range);
Result<FullTower> tower = guarded([&]() { return full_tower(session, cloud, full->k, local); });
if (!tower.ok()) return tower.outcome();
if (report != nullptr) {
  for (Stage stage : {Stage::cloud, Stage::index, Stage::domain, Stage::tree, Stage::attach})
    report->at(stage) = local.at(stage);
}
return Product(request, std::move(tower).take(), session.identity());

Result<OrderTree> build_order_full(FullDomain&& domain, Order k, MemoryBudget& budget, FullParams params,
                                   sched::Pool* pool, FullTimings* timings, u64* attach_ns,
                                   SeedLogRegisters* registers) noexcept {
  // Refus de parametres de build_full d'abord, puis l'ordre demande ; aucun effet avant.
  const Order kmax = domain.catalogue().kmax();
  if (kmax == 0 || kmax > domain.index().cloud().sites()) return fail(Reason::parameter_out_of_range);
  if (k == 0 || k > kmax) return fail(Reason::parameter_out_of_range);
  MHGP11_TRY(ForestParallel::validate(params, pool));
  FullTimings draft;
  // Journal admis avant toute allocation de FULL, par le majorant de build_order ; vit jusqu'au balayage.
  auto made = SeedLog::make(domain.catalogue(), k, budget);
  if (!made.ok()) return made.outcome();
  SeedLog log = std::move(made.value());
  std::array<std::optional<OrderForest>, kMaxMebSites> orders;
  MHGP11_TRY(build_forests(domain, kmax, budget, timings == nullptr ? nullptr : &draft, params, pool,
                           OrderLog{&log, k}, orders));
  log.close();
  const SeedLogRegisters logged = registers == nullptr ? SeedLogRegisters{} : registers_of(log);
  // Extraction : la seule foret d'ordre k, sans ses verticales ; les autres ordres rendus avant le balayage.
  OrderForest forest(std::move(*orders[k - 1]));
  for (auto& order : orders) order.reset();
  drop_verticals(forest);
  const Stopwatch clock;
  auto attachment = attach_window(domain, forest, log, budget);
  if (!attachment.ok()) return attachment.outcome();
  const u64 attached = clock.nanoseconds();
  log = SeedLog{};  // journal rendu avant le transfert du domaine
  if (timings != nullptr) *timings = draft;
  if (attach_ns != nullptr) *attach_ns = attached;
  if (registers != nullptr) *registers = logged;
  return OrderTree(std::move(domain), std::move(forest), std::move(attachment.value()));
